/* copy bytes:
 *  from = NULL  && bytes = 0
 *       to <- NULL
 *  from != NULL && bytes > 0
 *       to <- copy of from
 *  else ASSERT
 * malloc error leaves 'to' unchanged
 */
static FLAC__bool copy_bytes_(FLAC__byte **to, const FLAC__byte *from, uint32_t bytes)
{
        FLAC__ASSERT(to != NULL);
        if (bytes > 0 && from != NULL) {
                FLAC__byte *x;
                if ((x = safe_malloc_(bytes)) == NULL)
                        return false;
                memcpy(x, from, bytes);
                *to = x;
        }
        else {
                *to = 0;
        }
        return true;
}

